    if !current.is_empty() {
        lines.push(current);
    }
    let mut out = String::new();
    for (i, l) in lines.iter().enumerate() {
        let prefix = if i == 0 { first_prefix } else { cont_prefix };
        out.push_str(prefix);
        out.push_str(l);
        out.push('\n');
    }
    out
